    long long otherPart = length - halfPart;
    long long totalCells = n * m;

    long long answer;
    if (totalCells % 2 == 1) {
        answer = length % MOD;
    } else {
        long long sumParts = (modPow(halfPart + otherPart, totalCells, MOD) + modPow(abs(halfPart - otherPart), totalCells, MOD)) % MOD;
        answer = (sumParts * modInverse(2, MOD)) % MOD;
